-- dev_schema 台账种子（2026-10-05）：2 分组 + 2 真模型（全字段）+ e2e 导入探针表
-- id 段 1771000000000000xxx 固定（幂等重放前请先清 dev_* 台账行）

UPDATE `dev_schema` SET list_keys = 'id,user_name,real_name,nick_name,avatar,password,salt,mobile_phone,tel,email,admin_type,sex,is_locked,dept_id,post_id,remark,create_time,create_user,update_time,update_user' WHERE id = 1772000000000000001;
UPDATE `dev_schema` SET list_keys = 'id,name,code,data_type,group_code,sort,enabled,remark,variable,create_time,create_user,update_time,update_user' WHERE id = 1772000000000000002;

-- e2e 导入探针表（importTable 专用：一次覆盖 Textarea/Boolean 字典/ApiSelect/DatePicker 推断分支 + devtest 分组前缀匹配）
CREATE TABLE IF NOT EXISTS `devtest_import_probe` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `probe_name` varchar(64) NOT NULL COMMENT '名称',
  `probe_status` tinyint(1) DEFAULT 1 COMMENT '状态',
  `probe_remark` text COMMENT '备注',
  `dict_id` bigint(20) DEFAULT NULL COMMENT '字典',
  `probe_time` datetime DEFAULT NULL COMMENT '时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='dev 导入探针';
